import { z } from 'zod';
import { createResource, zodResolver } from 'qortex-resource';

const Schema = z.object({
  name: z.string().min(1, 'Required'),
  email: z.string().email(),
});

createResource({
  validate: {
    resolver: zodResolver(Schema),
    on: 'submit',
  },
  source: { save: (d) => api.save(d) },
});
